//! Lockfile-refresh workflow generated by `pixi-sandbox init`.
//!
//! The airlock's problem with dependencies is one-sided: a manifest edit is a text edit any
//! disconnected host can make, while the solve behind it needs prefix.dev and the crates.io
//! index — exactly what the host cannot reach, and `pixi add` solves before it writes. So the
//! connected side owns the solve. A contributor edits `pixi.toml` (or a `Cargo.toml`), pushes
//! a pull request with a stale lock, and this workflow refreshes the lockfiles onto that
//! branch as `pixi-sandbox[bot]`.
//!
//! Two properties of GitHub Actions shape the result, and both are traps when discovered late:
//!
//! 1. **A `GITHUB_TOKEN` push triggers no workflow** — deliberate loop prevention. The bot's
//!    lock commit would therefore sit with no CI verdict at all, so the last step dispatches
//!    the consumer's CI workflow explicitly (`workflow_dispatch` is an API call, which the
//!    token *is* allowed to make).
//! 2. **A fork pull request downgrades `contents: write` to read.** That is not a transient
//!    push failure, and it must not read as one: the job says so before it tries.
//!
//! Unlike the publisher template next door, every step here is a pinned `uses:` or a single
//! command, so the rendered file satisfies the repository's own workflow-shape rule without a
//! reviewed exception — which is what lets this repository commit its own render and prove,
//! byte for byte, that the artifact it runs is the artifact consumers get.

use super::GENERATED_MARKER;
use pixi_sandbox_core::sandbox_config::SandboxConfig;
use pixi_sandbox_core::tools_lock::ToolsLock;
use std::path::Path;

/// The identity automation commits carry: GitHub's bot convention is that the *name* holds the
/// tool identity while the address is the github-actions app's noreply, which is what makes a
/// commit render with the bot avatar instead of a broken-looking unknown author.
pub const BOT_NAME: &str = "pixi-sandbox[bot]";
/// Noreply address of the github-actions app, paired with [`BOT_NAME`].
pub const BOT_EMAIL: &str = "41898282+github-actions[bot]@users.noreply.github.com";

/// Inputs whose values vary independently of the reviewed workflow template.
#[derive(Debug, Clone, Copy)]
pub struct RelockWorkflowOptions<'a> {
    /// The pixi-sandbox CLI version that rendered this file, stamped beside the ownership
    /// marker (task-47 AC#3 / decision D16). Deliberately distinct from `pixi_version` below:
    /// one names this *tool's* release, the other names the *pixi binary* the bot solves with.
    pub cli_version: &'a str,
    /// Exact pixi version the bot solves with.
    ///
    /// This is the pin from the embedded tools lock, not "whatever is newest": the lockfile
    /// this bot writes has to be readable by the pixi a *transport* carries, and a restored
    /// airlock host cannot upgrade its pixi to catch up with a lock format written by a newer
    /// one. Pinning here keeps the connected and disconnected sides on one pixi.
    pub pixi_version: &'a str,
    /// Whether the project vendors Cargo dependencies, i.e. whether `Cargo.lock` is part of
    /// the lane. A project with no Rust in its transport gets no `cargo fetch` step.
    pub cargo: bool,
    /// Workflow file the bot dispatches after pushing a lock commit, relative to
    /// `.github/workflows/`.
    pub ci_workflow: &'a str,
    /// Workflow file the bot dispatches *after* that, so the refreshed lockfile is actually
    /// republished rather than left sitting on the branch — relative to `.github/workflows/`,
    /// and derived from the publisher path `init` was given, because a project that renamed its
    /// publisher would otherwise have a relock bot dispatching a workflow that does not exist.
    /// Without this the published transport carries the pre-relock lockfile indefinitely, and
    /// nothing reports the drift.
    pub publisher_workflow: &'a str,
}

/// The pixi pin compiled into this binary — the pixi a transport packed by it will carry, and
/// therefore the only version the bot may solve with. Returns `None` only if the embedded
/// catalogue stops declaring pixi at all, which the embedded-lock tests already forbid.
#[must_use]
pub fn embedded_pixi_pin() -> Option<String> {
    ToolsLock::embedded()
        .ok()?
        .tools
        .get("pixi")
        .map(|tool| tool.version.clone())
}

/// Whether `Cargo.lock` belongs in a project's relock lane, read off the same reviewed plan the
/// publisher uses. A plan that is absent or unreadable falls back to `true`, matching the plan
/// `init` writes for a new project: a spurious `cargo fetch` is a wasted minute, while a
/// missing one leaves a contributor's Cargo.lock stale with no signal.
#[must_use]
pub fn plan_vendors_cargo(config: &Path) -> bool {
    SandboxConfig::load(config).map_or(true, |plan| {
        plan.bundles.is_empty() && plan.cargo_vendor
            || plan
                .bundles
                .iter()
                .any(|bundle| bundle.cargo_vendor.unwrap_or(plan.cargo_vendor))
    })
}

/// Render the lockfile-refresh workflow.
#[must_use]
pub fn render_relock_workflow(options: RelockWorkflowOptions<'_>) -> String {
    let template = r#"# __GENERATED_MARKER__
# __VERSION_STAMP__
name: relock

# Refresh lockfiles for a manifest edit that was made where the network is not.
#
# The guard job reports on every pull request; the relock job runs only when the guard found
# drift, which is why this workflow carries no `paths:` filter — a stale lock arriving by any
# route (a transitive manifest, a hand-edited lock, a deleted one) is caught the same way.

on:
  pull_request:
  workflow_dispatch:

concurrency:
  group: relock-${{ github.head_ref || github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  guard:
    name: lock guard
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: prefix-dev/setup-pixi@d3f436a425481402e6a95a1d1fc10331c708cd9e # v0.10.2
        with:
          pixi-version: v__PIXI_VERSION__
          run-install: false
      # Ahead of any install on purpose: `setup-pixi` installs with `locked: true` and would
      # fail first with a message about installation, when the fact worth reporting is that the
      # lock no longer satisfies the manifest.
      - run: pixi lock --check

  relock:
    name: relock
    needs: guard
    # Only when the guard actually failed, and never on a dispatch — a dispatch re-runs the
    # guard alone, which is how the bot turns its own commit green (see the last step).
    if: ${{ always() && needs.guard.result == 'failure' && github.event_name == 'pull_request' }}
    runs-on: ubuntu-latest
    # A job-level `permissions:` block is a replacement, not an addition: every scope left
    # unlisted becomes `none`. `contents: write` alone therefore pushes the lock commit and
    # then fails the dispatch below with a 403, which is exactly how this was found.
    permissions:
      contents: write
      actions: write
    steps:
      # A fork PR downgrades `contents: write` to read, so the push below cannot succeed. Say
      # that, instead of letting a permissions wall read as a flaky push.
      - name: Refuse a fork pull request loudly
        if: ${{ github.event.pull_request.head.repo.fork }}
        run: echo "::error::relock cannot push to a fork's branch — the token is read-only on fork pull requests; run __LOCK_COMMANDS__ locally and push the lockfiles yourself" && exit 1
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.head_ref }}
          persist-credentials: true
      - uses: prefix-dev/setup-pixi@d3f436a425481402e6a95a1d1fc10331c708cd9e # v0.10.2
        with:
          pixi-version: v__PIXI_VERSION__
          run-install: false
      # Bare, not `pixi run <task>`: a task would first have to solve the very environment
      # whose lock is stale.
      - run: pixi lock
__CARGO_STEP__      - id: commit
        uses: stefanzweifel/git-auto-commit-action@4a55954c782fc1ea30b9056cd3e7a2b40ca8887d # v7.2.0
        with:
          commit_message: "chore(lock): refresh lockfiles for #${{ github.event.pull_request.number }}"
          commit_user_name: __BOT_NAME__
          commit_user_email: __BOT_EMAIL__
          commit_author: __BOT_NAME__ <__BOT_EMAIL__>
          file_pattern: __LOCK_FILES__
      # The push above used GITHUB_TOKEN, so it started nothing. These three dispatches are the
      # only verdict the lock commit will ever get: the consumer's CI, this workflow again
      # so its own guard reports green on the commit that fixed the drift, and the publisher so
      # the lockfile just refreshed reaches the transport instead of stalling on the branch.
      # The branch name reaches the command as an environment variable, never as inline
      # ${{ }}: a branch name is attacker-controlled text on a pull request, and interpolating
      # it into a shell line is the script-injection hole actionlint rejects.
      - if: ${{ steps.commit.outputs.changes_detected == 'true' }}
        run: gh workflow run __CI_WORKFLOW__ --ref "$HEAD_REF"
        env:
          GH_TOKEN: ${{ github.token }}
          HEAD_REF: ${{ github.head_ref }}
      - if: ${{ steps.commit.outputs.changes_detected == 'true' }}
        run: gh workflow run relock.yml --ref "$HEAD_REF"
        env:
          GH_TOKEN: ${{ github.token }}
          HEAD_REF: ${{ github.head_ref }}
      - if: ${{ steps.commit.outputs.changes_detected == 'true' }}
        run: gh workflow run __PUBLISHER_WORKFLOW__ --ref "$HEAD_REF"
        env:
          GH_TOKEN: ${{ github.token }}
          HEAD_REF: ${{ github.head_ref }}
"#;
    let cargo_step = if options.cargo {
        "      # Resolves only what the new constraint forces; `cargo update` would move the\n      # whole workspace, which is a different intent and a different pull request.\n      - run: cargo fetch\n"
    } else {
        ""
    };
    // The remedy a fork contributor is told to run is this project's actual lane, not a
    // generic one: a conda-only project has no cargo half to run.
    let lock_commands = if options.cargo {
        "'pixi lock' and 'cargo fetch'"
    } else {
        "'pixi lock'"
    };
    let lock_files = if options.cargo {
        "pixi.lock Cargo.lock"
    } else {
        "pixi.lock"
    };
    template
        .replace("__GENERATED_MARKER__", GENERATED_MARKER)
        .replace(
            "__VERSION_STAMP__",
            &super::version_stamp_line(options.cli_version),
        )
        .replace("__PIXI_VERSION__", options.pixi_version)
        .replace("__CARGO_STEP__", cargo_step)
        .replace("__LOCK_FILES__", lock_files)
        .replace("__LOCK_COMMANDS__", lock_commands)
        .replace("__CI_WORKFLOW__", options.ci_workflow)
        .replace("__PUBLISHER_WORKFLOW__", options.publisher_workflow)
        .replace("__BOT_NAME__", BOT_NAME)
        .replace("__BOT_EMAIL__", BOT_EMAIL)
}

#[cfg(test)]
mod tests {
    use super::{BOT_EMAIL, BOT_NAME, RelockWorkflowOptions, render_relock_workflow};

    /// The YAML a runner acts on, with the explanatory comments stripped — an absence
    /// assertion must not be satisfiable by prose, and this template deliberately *discusses*
    /// `pixi run`, `cargo fetch` and `paths:` in the comments that explain their absence.
    fn directives(workflow: &str) -> String {
        workflow
            .lines()
            .filter(|line| !line.trim_start().starts_with('#'))
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn render(cargo: bool) -> String {
        render_relock_workflow(RelockWorkflowOptions {
            cli_version: "9.8.7",
            pixi_version: "0.81.0",
            cargo,
            ci_workflow: "ci.yml",
            publisher_workflow: "publish-sandbox.yml",
        })
    }

    /// The whole point of generating this file rather than the publisher's shape: every step is
    /// a pinned `uses:` or one command, so a repository can commit its own render under a
    /// workflow-shape lint without a reviewed exception.
    #[test]
    fn every_step_is_an_action_or_a_single_command() {
        for workflow in [render(true), render(false)] {
            assert!(
                !workflow.contains("run: |") && !workflow.contains("run: >"),
                "the render must carry no block scalar: {workflow}"
            );
            assert!(!workflow.contains("shell: pwsh"), "{workflow}");
            for line in workflow.lines() {
                let trimmed = line.trim_start();
                if let Some(command) = trimmed.strip_prefix("- run: ").or(trimmed
                    .strip_prefix("run: ")
                    .filter(|_| trimmed.starts_with("run: ")))
                {
                    assert!(!command.is_empty(), "{workflow}");
                }
            }
        }
    }

    /// `pixi lock` cannot be a `pixi run <task>`: the task would have to solve the environment
    /// whose lock is the thing being refreshed.
    #[test]
    fn the_solve_commands_are_bare_not_pixi_tasks() {
        let workflow = render(true);
        assert!(workflow.contains("- run: pixi lock --check"), "{workflow}");
        assert!(workflow.contains("- run: pixi lock\n"), "{workflow}");
        assert!(!directives(&workflow).contains("pixi run"), "{workflow}");
    }

    /// The airlock constraint: the bot must not write a lockfile the pixi inside a transport
    /// cannot read, so the pin travels into the render instead of floating to newest.
    #[test]
    fn the_pixi_version_is_pinned_in_both_jobs() {
        let workflow = render(true);
        assert_eq!(workflow.matches("pixi-version: v0.81.0").count(), 2);
        assert_eq!(workflow.matches("run-install: false").count(), 2);
    }

    #[test]
    fn the_cargo_half_appears_only_for_a_vendoring_project() {
        let vendoring = render(true);
        assert!(vendoring.contains("- run: cargo fetch"), "{vendoring}");
        assert!(
            vendoring.contains("file_pattern: pixi.lock Cargo.lock"),
            "{vendoring}"
        );

        let conda_only = render(false);
        assert!(
            !directives(&conda_only).contains("cargo fetch"),
            "{conda_only}"
        );
        assert!(
            conda_only.contains("file_pattern: pixi.lock\n"),
            "{conda_only}"
        );
    }

    #[test]
    fn the_commit_is_conventional_and_authored_by_the_bot() {
        let workflow = render(true);
        assert!(
            workflow.contains(r#"commit_message: "chore(lock): refresh lockfiles for #"#),
            "{workflow}"
        );
        // Name and email set the committer; `commit_author` is what makes the bot the author.
        assert!(
            workflow.contains(&format!("commit_user_name: {BOT_NAME}")),
            "{workflow}"
        );
        assert!(
            workflow.contains(&format!("commit_user_email: {BOT_EMAIL}")),
            "{workflow}"
        );
        assert!(
            workflow.contains(&format!("commit_author: {BOT_NAME} <{BOT_EMAIL}>")),
            "{workflow}"
        );
    }

    /// A `GITHUB_TOKEN` push triggers nothing, so the dispatches are the lock commit's only
    /// verdict — and they only fire when a commit actually happened. The publisher is among
    /// them: a lockfile refreshed on the branch but never republished leaves the published
    /// transport holding the one the bot just replaced.
    #[test]
    fn the_dispatches_are_explicit_and_gated_on_a_real_commit() {
        let workflow = render(true);
        assert!(
            workflow.contains(r#"run: gh workflow run ci.yml --ref "$HEAD_REF""#),
            "{workflow}"
        );
        assert!(
            workflow.contains(r#"run: gh workflow run relock.yml --ref "$HEAD_REF""#),
            "{workflow}"
        );
        assert!(
            workflow.contains(r#"run: gh workflow run publish-sandbox.yml --ref "$HEAD_REF""#),
            "{workflow}"
        );
        // A branch name is attacker-controlled on a pull request, so it travels as an
        // environment variable instead of being interpolated into the command line.
        assert_eq!(
            workflow.matches("HEAD_REF: ${{ github.head_ref }}").count(),
            3
        );
        for line in workflow.lines().filter(|line| line.contains("run: ")) {
            assert!(!line.contains("${{"), "inline interpolation in {line}");
        }
        assert_eq!(
            workflow
                .matches("if: ${{ steps.commit.outputs.changes_detected == 'true' }}")
                .count(),
            3
        );
        assert_eq!(workflow.matches("GH_TOKEN: ${{ github.token }}").count(), 3);
    }

    /// The publisher dispatch names the publisher this project actually has, not a literal: a
    /// project that renamed its publisher via `--workflow-path` would otherwise get a relock bot
    /// dispatching a workflow that does not exist, and the failure lands on the bot, not on init.
    #[test]
    fn the_publisher_dispatch_follows_the_publisher_the_project_was_given() {
        let workflow = render_relock_workflow(RelockWorkflowOptions {
            cli_version: "9.8.7",
            pixi_version: "0.81.0",
            cargo: true,
            ci_workflow: "ci.yml",
            publisher_workflow: "publish-fork-sandbox.yaml",
        });
        assert!(
            workflow
                .contains(r#"run: gh workflow run publish-fork-sandbox.yaml --ref "$HEAD_REF""#),
            "{workflow}"
        );
        assert!(
            !workflow.contains("gh workflow run publish-sandbox.yml"),
            "{workflow}"
        );
    }

    #[test]
    fn a_consumer_can_dispatch_a_differently_named_ci_workflow() {
        let workflow = render_relock_workflow(RelockWorkflowOptions {
            cli_version: "9.8.7",
            pixi_version: "0.81.0",
            cargo: false,
            ci_workflow: "build-and-test.yml",
            publisher_workflow: "publish-sandbox.yml",
        });
        assert!(
            workflow.contains(r#"gh workflow run build-and-test.yml --ref "$HEAD_REF""#),
            "{workflow}"
        );
    }

    /// The guard runs everywhere; the push half is gated on the guard's verdict, on the event,
    /// and refuses a fork before it tries.
    #[test]
    fn the_relock_job_is_gated_on_the_guard_the_event_and_the_fork_check() {
        let workflow = render(true);
        assert!(
            workflow.contains(
                "if: ${{ always() && needs.guard.result == 'failure' && github.event_name == 'pull_request' }}"
            ),
            "{workflow}"
        );
        assert!(
            workflow.contains("if: ${{ github.event.pull_request.head.repo.fork }}"),
            "{workflow}"
        );
        assert!(
            workflow.contains("::error::relock cannot push to a fork's branch"),
            "{workflow}"
        );
        // The remedy names this project's lane, so a conda-only consumer is not told to run
        // a cargo command it has no use for.
        assert!(
            workflow.contains("run 'pixi lock' and 'cargo fetch' locally"),
            "{workflow}"
        );
        assert!(
            render(false).contains("run 'pixi lock' locally"),
            "the conda-only remedy must not mention cargo"
        );
        // Least privilege: the workflow is read-only and only the pushing job escalates.
        assert!(
            workflow.contains("permissions:\n  contents: read"),
            "{workflow}"
        );
        assert!(
            workflow.contains("    permissions:\n      contents: write"),
            "{workflow}"
        );
    }

    /// No `paths:` list: the guard's verdict is the trigger, so drift arriving by any route is
    /// caught rather than only drift under a configured path.
    #[test]
    fn the_trigger_is_the_guard_verdict_not_a_paths_filter() {
        let workflow = render(true);
        assert!(
            workflow.contains("on:\n  pull_request:\n  workflow_dispatch:"),
            "{workflow}"
        );
        assert!(!directives(&workflow).contains("paths:"), "{workflow}");
        assert!(
            workflow.contains("concurrency:\n  group: relock-${{ github.head_ref || github.ref }}\n  cancel-in-progress: true"),
            "{workflow}"
        );
    }

    #[test]
    fn the_pixi_pin_comes_from_the_embedded_catalogue() {
        let pin = super::embedded_pixi_pin().expect("the embedded lock always declares pixi");
        let embedded = pixi_sandbox_core::tools_lock::ToolsLock::embedded().expect("embedded");
        assert_eq!(pin, embedded.tools["pixi"].version);
    }

    #[test]
    fn the_cargo_decision_follows_the_plan_and_defaults_to_vendoring() {
        let dir = tempfile::tempdir().expect("tempdir");
        let config = dir.path().join("pixi-sandbox.toml");

        // No plan at all: a new project gets the lane init would write for it.
        assert!(super::plan_vendors_cargo(&config));

        std::fs::write(
            &config,
            "schema = 1\ncargo_vendor = false\n\n[[bundle]]\nname = \"developer\"\nenvironments = [\"default\"]\nplatforms = [\"linux-64\"]\n",
        )
        .expect("plan");
        assert!(!super::plan_vendors_cargo(&config));

        // One vendoring bundle is enough to put Cargo.lock in the lane.
        std::fs::write(
            &config,
            "schema = 1\ncargo_vendor = false\n\n[[bundle]]\nname = \"developer\"\nenvironments = [\"default\"]\nplatforms = [\"linux-64\"]\ncargo_vendor = true\n",
        )
        .expect("plan");
        assert!(super::plan_vendors_cargo(&config));
    }

    #[test]
    fn the_render_is_marked_as_generated() {
        assert!(render(true).starts_with("# Generated by pixi-sandbox init"));
    }

    /// task-47 AC#3: the relock workflow carries a parseable version stamp naming the CLI
    /// release it was rendered by — distinct from `PIXI_VERSION`, which pins the sandboxed
    /// pixi binary and has nothing to do with which pixi-sandbox release wrote this file.
    #[test]
    fn the_render_carries_a_parseable_version_stamp_for_the_cli_release() {
        let workflow = render_relock_workflow(RelockWorkflowOptions {
            cli_version: "4.5.6",
            pixi_version: "0.81.0",
            cargo: false,
            ci_workflow: "ci.yml",
            publisher_workflow: "publish-sandbox.yml",
        });
        assert_eq!(
            crate::generated::parse_version_stamp(&workflow),
            Some("4.5.6")
        );
        // The stamp names the CLI release, never the pinned pixi binary it also mentions.
        assert!(!workflow.contains("pixi-sandbox-version: 0.81.0"));
    }
}
